def run(ctx, args):
    """Geometry-aware probe that tracks template diversity and suggests next construction family."""
    best = ctx.best_score()
    budget_left = ctx.budget_left()
    evals_used = ctx.ledger.evaluator_calls if hasattr(ctx.ledger, 'evaluator_calls') else 0

    # Track which construction families have been tried (via state if available)
    state = ctx.get_state() if hasattr(ctx, 'get_state') else {}
    families_tried = state.get('families_tried', set())

    # Define construction families in order of recommended testing
    family_order = ['grid', 'trapezoid_3layer', 'hexagonal_shells', 'asymmetric_diamond', 'annular_tiered']
    recommended = None
    for family in family_order:
        if family not in families_tried:
            recommended = family
            break

    message = f"Best: {best:.6f}, Evaluated: {evals_used}, Budget left: {budget_left}"
    if recommended:
        message += f", Next recommended family: {recommended}"
    elif len(families_tried) >= 3:
        message += ", Tested multiple families - refine parameters or try hybrids"

    return {"best_score": best, "budget_left": budget_left, "message": message}

